mod solution;

fn main() {
    let cases = [
    (r#"Never odd or even"#, r#"true"#),
    (r#"Rust"#, r#"false"#),
    (r#"
Rust
"#, r#"false"#),
    (r#"  
Never odd or even
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS palindrome-pointers");
}
